import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText as _unused } from '@/text'; // ensure alias exists, not used directly

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container (scenePosition will be applied by the adapter)
  const root = new Group();

  // ---------- Plane ----------
  const geometry = new PlaneGeometry(7, 6); // size placeholder, can be adjusted as needed
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;
  material.opacity = 1;

  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture if provided
  let texture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // ---------- Text ----------
  const textItems = config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const texts = [];

  for (const item of textItems) {
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: item.typography?.fontSize ?? 39,
      color: config.visual?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    });
    // Position text slightly above the plane surface
    txt.position.set(0, 0, 0.01);
    root.add(txt);
    texts.push(txt);
  }

  // ---------- Primitives ----------
  // No cinematic primitives defined for this node, but keep placeholder
  const primitiveHandles = [];

  // ---------- Cleanup ----------
  function cleanup() {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();

    // Dispose any texts (they may hold their own resources)
    for (const txt of texts) {
      if (txt.geometry) txt.geometry.dispose?.();
      if (txt.material) txt.material.dispose?.();
    }

    // Kill any GSAP timelines (none in this node, but safety)
    gsap.globalTimeline.clear();

    // Cleanup primitives (none for this node)
    for (const ph of primitiveHandles) {
      if (ph && typeof ph.cleanup === 'function') ph.cleanup();
    }
  }

  // Attach handlers container (empty for this spec)
  root.userData.handlers = {};

  // Attach cleanup method
  root.userData.cleanup = cleanup;

  return root;
}
